# A complete analysis pipeline using pipes sentiment_extractor <- signature(   "feedback -> sentiment, issues: array(string)" ) |>   module(type = "predict")  response_generator <- signature("sentiment, issues -> response") |>   module(     type = "predict",     template = "Sentiment: {sentiment}
Issues: {issues}

Generate response:"   )  sentiment_step <- function(text, llm = NULL) {   result <- sentiment_extractor |>     run(       feedback = text,       .llm = llm,       .return_format = "structured"     )   result$output }  response_step <- function(analysis, llm = NULL) {   response_generator |>     run(       sentiment = analysis$sentiment,       issues = paste(analysis$issues, collapse = ", "),       .llm = llm     ) }  "The product quality is great but shipping was slow and packaging was damaged." |>   sentiment_step(llm = llm) |>   response_step(llm = llm)
